const tdengine = global.get('tdengine');
const database = env.get('TDENGINE_DATABASE') || 'test';
const user = env.get('TDENGINE_USER') || 'root';
const password = env.get('TDENGINE_PASSWORD') || 'taosdata';
const restBase = env.get('TDENGINE_REST_URL') || 'http://127.0.0.1:6041';
const wsUrl = env.get('TDENGINE_WS_URL') || restBase.replace(/^http/i, 'ws');
// 改成你的超级表、表和字段。
const sql = 'SELECT * FROM perf_apps';
let connection = context.get('tdengineWsConnection');
let rows;
try {
  if (!tdengine) throw new Error('未加载 @tdengine/websocket');
  if (!connection) {
    const config = new tdengine.WSConfig(wsUrl);
    config.setUser(user);
    config.setPwd(password);
    config.setDb(database);
    config.setTimeOut(10000);
    connection = await tdengine.sqlConnect(config);
    context.set('tdengineWsConnection', connection);
  }
  rows = await connection.query(sql);
  const meta = rows.getMeta() || [];
  const data = [];
  while (await rows.next()) data.push(...(rows.getData() || []));
  await rows.close();
  msg.payload = { code: 0, column_meta: meta.map((column) => [column.name, column.type, column.length]), data };
  node.status({ fill: 'green', shape: 'dot', text: 'WebSocket' });
  return [msg, null];
} catch (error) {
  try { await rows?.close(); } catch {}
  try { await connection?.close(); } catch {}
  context.set('tdengineWsConnection', undefined);
  node.status({ fill: 'yellow', shape: 'ring', text: 'REST fallback' });
  node.warn(`TDengine WebSocket 查询失败，回退 REST：${error.message || error}`);
  msg.method = 'POST';
  msg.url = `${restBase.replace(/\/$/, '')}/rest/sql/${encodeURIComponent(database)}`;
  msg.headers = { 'content-type': 'text/plain; charset=utf-8', authorization: `Basic ${Buffer.from(`${user}:${password}`).toString('base64')}` };
  msg.payload = sql;
  return [null, msg];
}

