const connection = context.get('tdengineWsConnection');
context.set('tdengineWsConnection', undefined);
if (connection) {
  try {
    Promise.resolve(connection.close()).catch((error) => node.warn(error));
  } catch (error) {
    node.warn(error);
  }
}

