const body = msg.payload || {};
if (body.status && body.status !== 'succ') { throw new Error(body.desc || 'TDengine 2.x 查询失败'); }
if (typeof body.code === 'number' && body.code !== 0) { throw new Error(body.desc || body.message || `TDengine 3.x 查询失败 (${body.code})`); }
const row = Array.isArray(body.data) ? body.data[0] : undefined;
const value = Array.isArray(row) ? row[row.length - 1] : row?.value;
msg.payload = Number(value ?? 0);
msg.topic = 'TDengine';
return msg;

const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
msg.payload = Number(row?.VALUE ?? row?.value ?? 0);
msg.topic = 'Oracle';
return msg;

const value = Number(msg.payload ?? 0);
const modelId = env.get('BIM_MODEL_ID') || '';
const base = { source: 'tdengine', key: 'value', value, timestamp: new Date().toISOString() };
const data = { ...msg, payload: base };
const scene = modelId ? { ...msg, payload: { ...base, key: 'alarmColor', value: value >= 80 ? '#ff4057' : value >= 60 ? '#d4a84f' : '#48b8ff', target: { modelId }, action: 'color' } } : null;
return [data, scene];

